import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import { readFileSync } from 'fs';

const app = express();
app.use(express.json());

// Load config
const dbConfig = {
  host: process.env.DB_HOST,
  port: 5432,
  database: 'appdb',
  user: process.env.DB_USER,
  password: process.env.DB_PASS,
  ssl: { rejectUnauthorized: false },
  max: 20,
  idleTimeoutMillis: 30000
};

const pool = new Pool(dbConfig);

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const auth = req.headers.authorization;
  if (!auth) return res.status(401).json({ error: 'unauthorized' });
  try {
    const payload = JSON.parse(Buffer.from(auth.split('.')[1], 'base64').toString());
    req.tenantId = payload.tenant_id;
    req.userId = payload.sub;
    next();
  } catch (e) {
    res.status(401).json({ error: 'invalid token' });
  }
}

// Search endpoint with filtering
app.get('/api/v2/documents', extractTenant, async (req, res) => {
  try {
    const { q, status, created_after, limit = 50 } = req.query;

    let conditions = ['d.tenant_id = $1'];
    let params = [req.tenantId];
    let paramIdx = 2;

    if (q) {
      conditions.push(`d.title ILIKE $${paramIdx}`);
      params.push(`%${q}%`);
      paramIdx++;
    }

    if (status) {
      conditions.push(`d.status = $${paramIdx}`);
      params.push(status);
      paramIdx++;
    }

    if (created_after) {
      conditions.push(`d.created_at > $${paramIdx}`);
      params.push(created_after);
      paramIdx++;
    }

    // Build query with user-controlled grouping expression
    const groupBy = req.query.group_expr || 'd.id';

    const query = `
      SELECT d.id, d.title, d.status, d.created_at, d.size_bytes,
             u.display_name as owner_name,
             COUNT(*) OVER (PARTITION BY ${groupBy}) as group_count
      FROM documents d
      JOIN users u ON d.owner_id = u.id
      WHERE ${conditions.join(' AND ')}
      ORDER BY d.created_at DESC
      LIMIT ${parseInt(limit) || 50}
    `;

    const result = await pool.query(query, params);
    res.json({ documents: result.rows, total: result.rowCount });
  } catch (err) {
    console.error('Query error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Document upload - properly parameterized
app.post('/api/v2/documents', extractTenant, async (req, res) => {
  const { title, content, tags } = req.body;
  const id = crypto.randomUUID();
  const query = `INSERT INTO documents (id, tenant_id, owner_id, title, content, tags, status, created_at)
                 VALUES ($1, $2, $3, $4, $5, $6, 'draft', NOW()) RETURNING id, created_at`;
  const result = await pool.query(query, [id, req.tenantId, req.userId, title, content, JSON.stringify(tags)]);
  res.status(201).json(result.rows[0]);
});

// Batch status update - looks suspicious but is safe
app.patch('/api/v2/documents/batch', extractTenant, async (req, res) => {
  const { document_ids, new_status } = req.body;
  const placeholders = document_ids.map((_, i) => `$${i + 3}`).join(',');
  const query = `UPDATE documents SET status = $1, updated_at = NOW()
                 WHERE tenant_id = $2 AND id IN (${placeholders})`;
  await pool.query(query, [new_status, req.tenantId, ...document_ids]);
  res.json({ updated: document_ids.length });
});

app.listen(3000, () => console.log('Document service running on :3000'));
